<script setup lang="ts">
import { onMounted,ref } from 'vue'
import { ShieldCheck,Sparkles,KeyRound,Activity } from 'lucide-vue-next'
import { api,post,session } from '../api'
const data=ref<any>(null),events=ref<any[]>([]),error=ref(''),message=ref(''),form=ref({old_password:'',password:''})
onMounted(async()=>{try{[data.value,events.value]=await Promise.all([api('dashboard/'),api('audit/')])}catch(e:any){error.value=e.message}})
async function password(){try{const data=await post('auth/password/',form.value);message.value=data.message;form.value={old_password:'',password:''}}catch(e:any){error.value=e.message}}
const actions:Record<string,string>={question_approved:'确认题目与参考答案',paper_published:'发布试卷快照',grade_updated:'评分 / 改分',batch_uploaded:'上传资料原件',batch_committed:'审核归档',practice_created:'生成针对练习',question_linked:'关联题库答案',question_split:'拆分题目',question_merged:'合并题块'}
</script>
<template><div class="page-heading"><div><p class="eyebrow">SETTINGS</p><h1>你的教学空间<span class="heading-dot">.</span></h1><p class="subtitle">账户、服务状态与每一次重要操作，都清楚可查。</p></div></div><div v-if="error" class="notice danger">{{error}}</div><div v-if="message" class="notice success">{{message}}</div><div class="profile-grid"><section class="panel padded"><div class="section-label"><h2>账户与数据</h2><ShieldCheck :size="21"/></div><dl class="settings-list"><dt>工作空间</dt><dd>{{session.user.workspace.name}}</dd><dt>登录邮箱</dt><dd>{{session.user.email}}</dd><dt>邮箱状态</dt><dd><span class="tag green">已验证</span></dd><dt>访问范围</dt><dd>仅当前教师的学生、题库、文件及报告</dd></dl></section><section v-if="data" class="panel padded"><div class="section-label"><h2>识别与AI服务</h2><Sparkles :size="21"/></div><dl class="settings-list"><dt>服务状态</dt><dd><span class="tag" :class="data.ai.configured?'green':'amber'">{{data.ai.configured?'已配置':'待管理员配置'}}</span></dd><dt>模型</dt><dd>{{data.ai.model||'尚未设置'}}</dd><dt>客观题自动定分</dt><dd>{{data.ai.auto_grading?'已启用':'验证前关闭，提供评分建议'}}</dd><dt>当前空间用量</dt><dd>{{data.ai.calls}} 次调用 · {{data.ai.tokens}} tokens</dd></dl><p class="helper">服务配置由服务器管理员管理。未配置时原件仍可保存；系统不会生成虚构的识别或评分结果。</p></section></div><section class="panel padded password-panel"><div class="section-label"><h2>修改密码</h2><KeyRound :size="20"/></div><form @submit.prevent="password"><div class="form-grid"><label>当前密码<input v-model="form.old_password" type="password" autocomplete="current-password" required/></label><label>新密码<input v-model="form.password" type="password" autocomplete="new-password" required minlength="8"/></label></div><button class="button primary">更新密码</button></form></section><section class="panel"><header class="panel-heading"><div><h2>操作记录</h2><p>保存审核、发布、评分及归档历史</p></div><Activity :size="20"/></header><div class="table-scroll"><table><thead><tr><th>操作</th><th>时间</th><th>关联记录</th></tr></thead><tbody><tr v-for="event in events.slice(0,50)" :key="event.id"><td>{{actions[event.action]||event.action}}</td><td>{{new Date(event.created_at).toLocaleString('zh-CN')}}</td><td class="muted small">{{event.object_id.slice(0,8)}}</td></tr><tr v-if="!events.length"><td colspan="3">暂无操作记录</td></tr></tbody></table></div></section></template>
